\begin{tikzpicture}[x=0.65cm,y=0.65cm,every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\draw[->,line width=0.5pt] (-2.4,0)--(4.2,0) node[right] {$x$};
