\node (rightintercept) at (3,-1.35) {$(3,0)$};\draw[line width=.25pt] (rightintercept.north)--(3,0);
\node[anchor=west] at (-2.2,-2.4) {$y=2x+3$ (solid)};
\node[anchor=west] at (-2.2,-3.3) {$y=-x+3$ (dashed)};
\end{tikzpicture}

